import json
import sys

from totals import totals


def main():
    try:
        output = json.dumps(totals(sys.stdin), sort_keys=True)
    except (ValueError, OSError):
        print('error: invalid CSV input', file=sys.stderr)
        return 2
    print(output)
    return 0


if __name__ == '__main__':
    sys.exit(main())

