import csv
import re
from decimal import Decimal, InvalidOperation


_NUMBER = re.compile(r'[+-]?(?:[0-9]+(?:\.[0-9]*)?|\.[0-9]+)(?:[eE][+-]?[0-9]+)?')


def _cents(text):
    text = text.strip()
    if not _NUMBER.fullmatch(text):
        raise ValueError('invalid amount')
    try:
        amount = Decimal(text)
    except InvalidOperation:
        raise ValueError('invalid amount') from None
    if not amount.is_finite():
        raise ValueError('invalid amount')
    sign, digits, exponent = amount.as_tuple()
    if exponent < -2:
        raise ValueError('amount has more than two decimal places')
    # Integer arithmetic keeps every cent, regardless of Decimal context precision.
    value = 0
    for digit in digits:
        value = value * 10 + digit
    value *= 10 ** (exponent + 2)
    return -value if sign else value


def _format_cents(value):
    whole, fraction = divmod(abs(value), 100)
    return f'{"-" if value < 0 else ""}{whole}.{fraction:02d}'


def totals(stream):
    result = {}
    try:
        reader = csv.DictReader(stream, strict=True)
        while reader.fieldnames == []:
            reader.fieldnames = None
        if reader.fieldnames is None:
            return {}
        if len(reader.fieldnames) != 2 or set(reader.fieldnames) != {'category', 'amount'}:
            raise ValueError('expected category and amount columns')
        for row in reader:
            if None in row or any(value is None for value in row.values()):
                raise ValueError('expected two fields per row')
            category = row['category'].strip()
            if not category:
                raise ValueError('empty category')
            result[category] = result.get(category, 0) + _cents(row['amount'])
    except csv.Error:
        raise ValueError('invalid CSV') from None
    return {category: _format_cents(result[category]) for category in sorted(result)}

