def merge(values):
    if not isinstance(values, list):
        raise ValueError('values must be a list of integer interval tuples')

    for interval in values:
        if not isinstance(interval, tuple) or len(interval) != 2:
            raise ValueError('each interval must be a two-element tuple')
        start, end = interval
        if type(start) is not int or type(end) is not int or start > end:
            raise ValueError('interval endpoints must be integers with start <= end')

    merged = []
    for start, end in sorted(values, key=lambda interval: interval[0]):
        if merged and start <= merged[-1][1]:
            merged[-1] = (merged[-1][0], max(merged[-1][1], end))
        else:
            merged.append((start, end))
    return merged
